<?php
function item_codes_ready(){return setting('item_codes_version','')==='5.4.1';}
function migrate_item_codes(){if(!adjustments_ready())throw new Exception('Run the V5.4.0 Adjustments & Reports upgrade first.');db()->exec("CREATE TABLE IF NOT EXISTS product_code_aliases(alias_code VARCHAR(60) PRIMARY KEY,product_id INT NOT NULL,original_code VARCHAR(60) NOT NULL,migration_ref VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(product_id)) ENGINE=InnoDB");db()->exec("CREATE TABLE IF NOT EXISTS code_reset_runs(id BIGINT AUTO_INCREMENT PRIMARY KEY,run_ref VARCHAR(100) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL,backup_id BIGINT NOT NULL,plan_json LONGTEXT NOT NULL,review_digest CHAR(64) NOT NULL,result_json LONGTEXT NULL,created_by INT NOT NULL,applied_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,applied_at DATETIME NULL) ENGINE=InnoDB");set_setting('item_codes_version','5.4.1');set_setting('product_status_version','5.4.2');}
function product_code_lookup($code){$code=trim((string)$code);if($code==='')return 0;$q=db()->prepare('SELECT id FROM products WHERE master_sku=? AND active=1');$q->execute([$code]);if($id=$q->fetchColumn())return (int)$id;if(!item_codes_ready())return 0;$q=db()->prepare('SELECT a.product_id FROM product_code_aliases a JOIN products p ON p.id=a.product_id WHERE a.alias_code=? AND p.active=1');$q->execute([norm($code)]);return (int)$q->fetchColumn();}
function item_code_scope(){$scope=['clear'=>['count_review_events','count_upload_evidence','adjustment_movements','daily_closing_versions','inventory_count_lines','inventory_count_batches','threshold_lines','threshold_batches','receipt_staging_lines','inflow_receipt_claims','posted_returns','return_batches','borrowed_events','borrowed_items','repackaging_batch_lines','repackaging_batches','packaging_completions','transaction_reversals','stock_events','stock_exceptions','day_closings','process_reconciliations','nonsellable_release_links','nonsellable_outflows','non_sellable','inflows','outflows','unmapped_imports','import_batches','inflow_batches','return_exceptions','allocation_lines','allocation_batches','allocation_override_history','platform_transfers','platform_stock','beginning_balances','reconciliations','reconciliation_batches','activity_log'],'keep'=>['products','brands','categories','platform_aliases','receipt_aliases','users','allocation_rules','product_audit','settings','managed_categories','category_sequences','process_backups','product_code_aliases','code_reset_runs']];if(brand_sku_runs_ready())$scope['keep'][]='sku_conversion_runs';if(function_exists('om_ready')&&om_ready()){$scope['clear']=array_merge(['om_alerts','om_reservation_events','om_events','om_postings','om_reservations','om_lines','om_orders','om_uploads','om_sessions'],$scope['clear']);$scope['keep'][]='om_mappings';}return $scope;}
function item_code_snapshot(){global $CFG;$scope=item_code_scope();$actual=db()->query("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")->fetchAll(PDO::FETCH_COLUMN);$expected=array_merge(...array_values($scope));$unknown=array_merge(array_diff($actual,$expected),array_diff($expected,$actual));if($unknown)throw new Exception('Unreviewed tables: '.implode(', ',$unknown).'. Reset blocked.');$out=[];foreach($actual as $t){$q=db()->prepare('SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND TABLE_NAME=?');$q->execute([$CFG['db_name'],$t]);if($q->fetchColumn()!=='InnoDB')throw new Exception('InnoDB required: '.$t);if($t==='code_reset_runs')continue;$rows=db()->query('SELECT * FROM `'.$t.'`')->fetchAll();$out[$t]=['rows'=>count($rows),'hash'=>backup_rows_hash($rows)];}ksort($out);return $out;}
function item_code_plan(){
 if(brand_sku_enabled())return brand_sku_plan(true);
 if(!item_codes_ready())throw new Exception('Run upgrade_item_codes.php first.');$products=db()->query('SELECT * FROM products ORDER BY id')->fetchAll();$sequences=array_column(db()->query('SELECT * FROM category_sequences')->fetchAll(),null,'category_key');$reserved=[];foreach($products as $p)if(trim((string)$p['master_sku'])!=='')$reserved[norm($p['master_sku'])]=(int)$p['id'];foreach(db()->query('SELECT * FROM product_code_aliases') as $r){$key=norm($r['alias_code']);if(isset($reserved[$key])&&$reserved[$key]!=(int)$r['product_id'])throw new Exception('An old code conflicts with another product: '.$r['alias_code']);$reserved[$key]=(int)$r['product_id'];}
 $knownExternal=db()->query('SELECT product_id,alias,external_id FROM platform_aliases')->fetchAll();foreach($knownExternal as $r)foreach(['alias','external_id'] as $field){$v=trim((string)$r[$field]);if(!preg_match('/^[A-Za-z0-9]{1,12}-[0-9]{4,}$/D',$v))continue;$key=norm($v);if(isset($reserved[$key])&&$reserved[$key]!=(int)$r['product_id'])throw new Exception('Platform code conflicts with another product: '.$v.'. Review its mapping first.');$reserved[$key]=(int)$r['product_id'];}
 $grouped=[];foreach($products as $p){[$main,$sub]=product_category_selection($p['main_category'],$p['category']);$seqKey=category_key($main,$sub===$main?'':$sub);if(!isset($sequences[$seqKey]))throw new Exception('Missing category prefix for '.$main.' / '.$sub.'. Review categories first.');$grouped[$seqKey][]=$p;}$lines=[];$groups=[];
 foreach($grouped as $key=>$ps){$seq=$sequences[$key];$prefix=$seq['prefix'];$used=[];$assigned=[];foreach($ps as $p)if(preg_match('/^'.preg_quote($prefix,'/').'-(\d{4,})$/D',(string)$p['master_sku'],$m)&&(int)$m[1]>0){$used[(int)$m[1]]=true;$assigned[$p['id']]=$p['master_sku'];}foreach($ps as $p){$new=$assigned[$p['id']]??null;if(!$new){$n=1;do{$candidate=$prefix.'-'.str_pad((string)$n,4,'0',STR_PAD_LEFT);$taken=isset($used[$n])||(isset($reserved[norm($candidate)])&&$reserved[norm($candidate)]!==(int)$p['id']);if($taken)$n++;}while($taken);$new=$candidate;$used[$n]=true;$reserved[norm($new)]=(int)$p['id'];}$lines[]=['id'=>(int)$p['id'],'old'=>$p['master_sku'],'new'=>$new,'name'=>$p['name'],'brand'=>$p['brand'],'main'=>$p['main_category'],'sub'=>$p['category'],'active'=>(int)$p['active']];}$groups[$key]=['prefix'=>$prefix,'main'=>$ps[0]['main_category'],'sub'=>$ps[0]['category'],'products'=>count($ps),'next_number'=>max((int)$seq['next_number'],max(array_keys($used))+1)];}
 usort($lines,fn($a,$b)=>[$a['main'],$a['sub'],$a['new']]<=>[$b['main'],$b['sub'],$b['new']]);return ['lines'=>$lines,'groups'=>$groups,'changed'=>count(array_filter($lines,fn($r)=>$r['old']!==$r['new'])),'snapshot'=>item_code_snapshot()];
}
function item_code_require_admin(){if(current_user()['role']!=='Admin')throw new Exception('Administrator access required.');if(!item_codes_ready())throw new Exception('Run upgrade_item_codes.php first.');}
function item_code_prepare(){throw new Exception('Combined reset and SKU renumbering is retired. Use Fresh Start for Inventory / Transaction Reset only.');item_code_require_admin();item_code_plan();$backup=backup_create();backup_verify_restore($backup);$plan=item_code_plan();$ref=next_ref('START').'-'.bin2hex(random_bytes(3));$digest=hash('sha256',json_encode($plan));db()->prepare("INSERT INTO code_reset_runs(run_ref,status,backup_id,plan_json,review_digest,created_by) VALUES(?,'Prepared',?,?,?,?)")->execute([$ref,$backup,json_encode($plan),$digest,current_user()['id']]);return (int)db()->lastInsertId();}
function item_code_run($id){$q=db()->prepare('SELECT * FROM code_reset_runs WHERE id=?');$q->execute([(int)$id]);$r=$q->fetch();if(!$r)throw new Exception('Fresh-start preparation not found.');return $r;}
function item_code_apply($id,$digest,$confirmation,$ack){throw new Exception('Combined reset and SKU renumbering is retired. Use the current Fresh Start form.');item_code_require_admin();if(!$ack||$confirmation!=='RESET STOCKS AND RENUMBER')throw new Exception('Review the scope and type RESET STOCKS AND RENUMBER to confirm.');return process_transaction(function()use($id,$digest){$q=db()->prepare('SELECT * FROM code_reset_runs WHERE id=? FOR UPDATE');$q->execute([$id]);$run=$q->fetch();if(!$run||$run['status']!=='Prepared')throw new Exception('This reset is already applied or unavailable.');if(!hash_equals($run['review_digest'],(string)$digest))throw new Exception('Review token changed. Prepare again.');$plan=json_decode($run['plan_json'],true,512,JSON_THROW_ON_ERROR);if(item_code_plan()!==$plan)throw new Exception('Products, stocks, settings or history changed since preparation. Create a fresh backup and preview.');$backup=backup_record($run['backup_id']);if($backup['restore_test_status']!=='Passed')throw new Exception('A verified backup restore test is required.');$z=new ZipArchive();if($z->open($backup['path'])!==true)throw new Exception('Backup is unreadable.');try{$m=json_decode($z->getFromName('backup_manifest.json'),true,512,JSON_THROW_ON_ERROR);foreach($m['files'] as $name=>$hash)if(!hash_equals($hash,hash('sha256',$z->getFromName($name))))throw new Exception('Backup integrity failed.');}finally{$z->close();}
 $preserved=[];foreach(item_code_scope()['keep'] as $t)if(!in_array($t,['products','settings','category_sequences','product_code_aliases','code_reset_runs'],true))$preserved[$t]=backup_rows_hash(db()->query('SELECT * FROM `'.$t.'`')->fetchAll());$oldProducts=db()->query('SELECT * FROM products ORDER BY id FOR UPDATE')->fetchAll();$oldSettings=db()->query("SELECT * FROM settings WHERE key_name<>'beginning_locked' ORDER BY key_name")->fetchAll();
 foreach(item_code_scope()['clear'] as $t)db()->exec('DELETE FROM `'.$t.'`');set_setting('beginning_locked','0');
 foreach($plan['lines'] as $l){if(trim((string)$l['old'])!==''){db()->prepare('INSERT INTO product_code_aliases(alias_code,product_id,original_code,migration_ref) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE alias_code=VALUES(alias_code)')->execute([norm($l['old']),$l['id'],$l['old'],$run['run_ref']]);}if($l['old']!==$l['new'])db()->prepare('UPDATE products SET master_sku=? WHERE id=?')->execute(['TMP-'.substr(hash('sha256',$run['run_ref']),0,12).'-'.$l['id'],$l['id']]);}
 foreach($plan['lines'] as $l)if($l['old']!==$l['new'])db()->prepare('UPDATE products SET master_sku=? WHERE id=?')->execute([$l['new'],$l['id']]);foreach($plan['groups'] as $key=>$g)db()->prepare('UPDATE category_sequences SET next_number=GREATEST(next_number,?) WHERE category_key=?')->execute([$g['next_number'],$key]);
 $newProducts=db()->query('SELECT * FROM products ORDER BY id')->fetchAll();$clean=function($rows){foreach($rows as &$r){unset($r['master_sku'],$r['updated_at']);}return $rows;};if($clean($oldProducts)!==$clean($newProducts))throw new Exception('Unexpected product changes. Reset rolled back.');if($oldSettings!==db()->query("SELECT * FROM settings WHERE key_name<>'beginning_locked' ORDER BY key_name")->fetchAll())throw new Exception('Settings changed.');foreach($preserved as $t=>$hash)if(!hash_equals($hash,backup_rows_hash(db()->query('SELECT * FROM `'.$t.'`')->fetchAll())))throw new Exception('Master data changed: '.$t);foreach(item_code_scope()['clear'] as $t)if((int)db()->query('SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn())throw new Exception('Stock/history reset incomplete: '.$t);
 foreach($plan['lines'] as $l){$q=db()->prepare('SELECT master_sku FROM products WHERE id=?');$q->execute([$l['id']]);if($q->fetchColumn()!==$l['new'])throw new Exception('Code verification failed.');if($l['active']&&$l['old']&&product_code_lookup($l['old'])!==$l['id'])throw new Exception('Old-code lookup verification failed.');}
 $result=['products'=>count($plan['lines']),'codes_changed'=>$plan['changed'],'stocks_zero'=>true,'test_history_cleared'=>true,'mappings_users_categories_settings_preserved'=>true,'beginning_balance_unlocked'=>true,'backup_id'=>(int)$run['backup_id']];db()->prepare("UPDATE code_reset_runs SET status='Applied',result_json=?,applied_by=?,applied_at=NOW() WHERE id=?")->execute([json_encode($result),current_user()['id'],$id]);audit('Fresh start and item codes','System',$run['run_ref'],json_encode($result));return $result;});}
